function i(t){if(t<=0)return"0 GB";const e=t/1024**3;if(e>=1)return`${e.toFixed(1).replace(".",",")} GB`;const r=t/1024**2;return`${Math.round(r)} MB`}function o(t){return new Intl.NumberFormat("pt-PT").format(t)}function s(t){const e=typeof t=="string"?new Date(t):t;return Number.isNaN(e.getTime())?"—":new Intl.DateTimeFormat("pt-PT",{day:"2-digit",month:"long",year:"numeric"}).format(e)}function m(t){return t.split(" ").filter(Boolean).slice(0,2).map(e=>e[0]?.toUpperCase()??"").join("")}function c(t){return/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(t.trim())}function f(t){const e=[{label:"Pelo menos 8 caracteres",ok:t.length>=8},{label:"Uma letra maiúscula",ok:/[A-Z]/.test(t)},{label:"Uma letra minúscula",ok:/[a-z]/.test(t)},{label:"Um número",ok:/\d/.test(t)}],r=e.filter(n=>n.ok).length;return{score:r,label:["Muito fraca","Fraca","Razoável","Boa","Forte"][r]??"Muito fraca",checks:e}}function l(t){if(t==="")return"—";const e=typeof t=="string"?new Date(t):t;return Number.isNaN(e.getTime())?typeof t=="string"?t:"—":new Intl.DateTimeFormat("pt-PT",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(e)}export{c as a,i as b,o as c,l as d,s as f,m as i,f as p};
